{"command": "python3 -c "
from PIL import Image, ImageOps
im = Image.open('radiograph.jpg').convert('L')
W,H=im.size
tiles={
't1':(0,200,830,760),'t2':(780,200,1610,760),'t3':(1560,200,2444,760),
't4':(0,700,830,1120),'t5':(780,700,1610,1120),'t6':(1560,700,2444,1120),
}
for k,b in tiles.items():
    c=im.crop(b); c=c.resize((int(c.width*2.2),int(c.height*2.2)),Image.LANCZOS)
    c=ImageOps.autocontrast(c,cutoff=0)
    c.save(f'/tmp/{k}.png'); print(k,c.size)
"", "description": "Six large tiles at 2.2x"}

